<!--
 * 消息模板列表页组件
 *
 * @path apps/message-web/src/views/template/index.vue
 * @author ydsz-team
 * @since 1.0.0
 * @modified 4.1.0 由脚手架 CRUD 重写为消费契约 API（page/create/update/deleteApi/audit）。
-->
<script lang="ts" setup>
/**
 * 消息模板（列表页）
 * <p>消费后端契约 TemplateController（src/api/template.ts，auto-generated by bash/gen-contract.py）：
 * page() 分页查询模板，行操作「编辑」打开 template-form.vue、「审核」调 audit({id})、
 * 「删除」调 deleteApi({id})。列字段以 MsgTemplateVO 为准。
 *
 * @author ydsz-team
 * @since 1.0.0
 */
import type { VxeTableGridOptions } from '@ydsz/plugins/vxe-table';

import { Page, useYDSZModal } from '@ydsz/common-ui';

import {
  ElButton,
  ElDialog,
  ElDrawer,
  ElForm,
  ElFormItem,
  ElInput,
  ElMessage,
  ElMessageBox,
  ElTag,
} from 'element-plus';
import { h, reactive, ref } from 'vue';
import { useI18n } from 'vue-i18n';

import { useYDSZVxeGrid } from '#/adapter/vxe-table';
import { audit, deleteApi, page } from '#/api/template';
import { listVersions, preview, rollback, testSend } from '#/api/templateVersion';
import type { MsgTemplateVO, MsgTemplateVersion } from '#/api/models';

import TemplateForm from './template-form.vue';

defineOptions({ name: 'TemplateManagement' });

const { t } = useI18n();

/** 审核状态列 Tag 类型映射（未知值按 info 展示） */
function getAuditStatusType(auditStatus?: string): 'success' | 'danger' | 'warning' | 'info' {
  const upper = (auditStatus ?? '').toUpperCase();
  if (['APPROVED', 'PASS'].includes(upper)) return 'success';
  if (['REJECTED', 'FAIL'].includes(upper)) return 'danger';
  if (['PENDING', 'SUBMITTED'].includes(upper)) return 'warning';
  return 'info';
}

const gridOptions: VxeTableGridOptions<MsgTemplateVO> = {
  columns: [
    { type: 'seq', width: 50, title: t('common.seq') },
    { field: 'templateCode', title: t('templateCode'), width: 160 },
    { field: 'channel', title: '通道', width: 100 },
    { field: 'category', title: t('category'), width: 100 },
    { field: 'sceneCode', title: '场景编码', width: 120 },
    { field: 'subject', title: '主题', width: 180 },
    { field: 'provider', title: '供应商', width: 110 },
    { field: 'version', title: t('version'), width: 80 },
    {
      field: 'auditStatus',
      title: '审核状态',
      width: 100,
      slots: {
        default: ({ row }) =>
          h(ElTag, { type: getAuditStatusType(row.auditStatus) }, () => row.auditStatus ?? '-'),
      },
    },
    {
      field: 'status',
      title: t('common.status'),
      width: 90,
      slots: {
        default: ({ row }) =>
          h(
            ElTag,
            { type: row.status === 'DISABLED' ? 'info' : 'success' },
            () => row.status ?? '-',
          ),
      },
    },
    { field: 'createdAt', title: t('common.createTime'), width: 170 },
    {
      field: 'action',
      title: t('common.actions'),
      width: 200,
      fixed: 'right',
      slots: {
        default: ({ row }) =>
          h('div', { class: 'flex gap-1' }, [
            h(
              ElButton,
              { size: 'small', link: true, type: 'primary', onClick: () => handleEdit(row) },
              () => t('common.edit'),
            ),
            h(
              ElButton,
              { size: 'small', link: true, type: 'primary', onClick: () => handleVersion(row) },
              () => t('version'),
            ),
            h(
              ElButton,
              { size: 'small', link: true, type: 'success', onClick: () => handlePreview(row) },
              () => '预览',
            ),
            h(
              ElButton,
              { size: 'small', link: true, type: 'warning', onClick: () => handleTestSend(row) },
              () => '测试',
            ),
            h(
              ElButton,
              { size: 'small', link: true, type: 'warning', onClick: () => handleAudit(row) },
              () => '审核',
            ),
            h(
              ElButton,
              { size: 'small', link: true, type: 'danger', onClick: () => handleDelete(row) },
              () => t('common.delete'),
            ),
          ]),
      },
    },
  ],
  height: 'auto',
  pagerConfig: { pageSize: 20, pageSizes: [10, 20, 50, 100] },
  proxyConfig: {
    ajax: {
      query: async (_page, formValues) => {
        const res = await page({ query: { ...formValues } });
        return { items: res.data ?? [], total: res.total ?? 0 };
      },
    },
  },
  toolbarConfig: { custom: true, refresh: { code: 'query' }, search: true, zoom: true },
  formConfig: {
    enabled: true,
    items: [
      {
        field: 'templateCode',
        title: t('templateCode'),
        itemRender: { name: 'Input', props: { placeholder: t('templateCode') } },
      },
      {
        field: 'channel',
        title: '通道',
        itemRender: { name: 'Input', props: { placeholder: '通道' } },
      },
      {
        field: 'auditStatus',
        title: '审核状态',
        itemRender: { name: 'Input', props: { placeholder: '审核状态' } },
      },
    ],
  },
};

const [Grid, gridApi] = useYDSZVxeGrid({ gridOptions });

const [TemplateFormModal, templateFormApi] = useYDSZModal({ connectedComponent: TemplateForm });

function handleAdd() {
  templateFormApi.open();
}

function handleEdit(row: MsgTemplateVO) {
  templateFormApi.setData({ record: row });
  templateFormApi.open();
}

async function handleAudit(row: MsgTemplateVO) {
  if (!row.id) return;
  try {
    const { value: remark } = await ElMessageBox.prompt('请输入审核备注（可为空）', '审核通过', {
      type: 'warning',
      inputPlaceholder: '审核备注',
    });
    await audit({ id: row.id }, { auditStatus: 'APPROVED', auditRemark: remark ?? undefined });
    ElMessage.success('审核通过');
    gridApi.query();
  } catch {
    // 用户取消或请求失败
  }
}

async function handleDelete(row: MsgTemplateVO) {
  if (!row.id) return;
  try {
      await ElMessageBox.confirm(`确定删除模板「${row.templateCode}」吗？`, t('deleteConfirmTitle'), {
      type: 'warning',
    });
    await deleteApi({ id: row.id });
    ElMessage.success(t('deleteSuccess'));
    gridApi.query();
  } catch {
    // 用户取消或请求失败
  }
}

/** 版本管理抽屉状态 */
const versionVisible = ref(false);
const versionLoading = ref(false);
const versionList = ref<MsgTemplateVersion[]>([]);
const currentTemplateCode = ref('');

/** 打开版本管理 */
async function handleVersion(row: MsgTemplateVO) {
  if (!row.templateCode) return;
  currentTemplateCode.value = row.templateCode;
  versionVisible.value = true;
  versionLoading.value = true;
  try {
    versionList.value = await listVersions({ templateCode: row.templateCode });
  } catch {
    versionList.value = [];
  } finally {
    versionLoading.value = false;
  }
}

/** 版本回滚 */
async function handleRollback(version: MsgTemplateVersion) {
  if (!version.version) return;
  try {
    await ElMessageBox.confirm(`确定回滚到版本 ${version.version} 吗？`, '回滚确认', {
      type: 'warning',
    });
    await rollback({ templateCode: currentTemplateCode.value, version: version.version });
    ElMessage.success('回滚成功');
    await handleVersion({ templateCode: currentTemplateCode.value });
  } catch {
    // 用户取消或请求失败
  }
}

/** 预览弹窗状态 */
const previewVisible = ref(false);
const previewContent = ref('');
const previewLoading = ref(false);

/** 打开预览 */
async function handlePreview(row: MsgTemplateVO) {
  if (!row.templateCode) return;
  previewVisible.value = true;
  previewLoading.value = true;
  try {
    const result = await preview({
      templateCode: row.templateCode,
      variables: {},
    });
    previewContent.value = result ?? '';
  } catch {
    previewContent.value = '预览生成失败';
  } finally {
    previewLoading.value = false;
  }
}

/** 测试发送弹窗状态 */
const testSendVisible = ref(false);
const testSendForm = reactive({ receiver: '', variables: '' });

/** 打开测试发送 */
function handleTestSend(_row: MsgTemplateVO) {
  testSendForm.receiver = '';
  testSendForm.variables = '';
  testSendVisible.value = true;
}

/** 执行测试发送 */
async function executeTestSend(): Promise<void> {
  if (!testSendForm.receiver.trim()) {
    ElMessage.warning('请输入接收人');
    return;
  }
  try {
    await testSend({
      templateCode: '',
      receiver: testSendForm.receiver,
      variables: {},
    });
    ElMessage.success('测试发送成功');
    testSendVisible.value = false;
  } catch {
    // 错误提示由请求拦截器统一处理
  }
}
</script>
<template>
  <Page auto-content-height>
    <Grid table-title="模板管理">
      <template #toolbar-tools>
        <ElButton type="primary" @click="handleAdd">{{ t('common.create') }}</ElButton>
      </template>
    </Grid>
    <TemplateFormModal @success="gridApi.query()" />
    <!-- 版本管理抽屉 -->
    <ElDrawer v-model="versionVisible" title="版本管理" :size="640">
      <div v-loading="versionLoading">
        <div v-if="versionList.length === 0" class="py-8 text-center text-gray-400">
          暂无版本记录
        </div>
        <div
          v-for="version in versionList"
          :key="version.version"
          class="mb-3 flex items-center justify-between rounded border p-3"
        >
          <div>
            <p class="text-sm font-medium">版本 {{ version.version }}</p>
            <p class="text-xs text-gray-500">{{ version.createdAt }}</p>
            <p v-if="version.changeLog" class="mt-1 text-xs text-gray-600">
              {{ version.changeLog }}
            </p>
          </div>
          <ElButton size="small" type="warning" @click="handleRollback(version)">回滚</ElButton>
        </div>
      </div>
    </ElDrawer>
    <!-- 预览弹窗 -->
    <ElDialog v-model="previewVisible" title="模板预览" width="600px">
      <div v-loading="previewLoading" class="min-h-32">
        <pre class="overflow-auto whitespace-pre-wrap rounded bg-gray-50 p-4 text-sm">{{
          previewContent
        }}</pre>
      </div>
    </ElDialog>
    <!-- 测试发送弹窗 -->
    <ElDialog v-model="testSendVisible" title="测试发送" width="480px">
      <ElForm :model="testSendForm" label-width="80px">
        <ElFormItem label="接收人" required>
          <ElInput v-model="testSendForm.receiver" placeholder="请输入接收人邮箱/手机号" />
        </ElFormItem>
        <ElFormItem label="变量">
          <ElInput
            v-model="testSendForm.variables"
            placeholder="请输入变量JSON（选填）"
            type="textarea"
            :rows="3"
          />
        </ElFormItem>
      </ElForm>
      <template #footer>
        <ElButton @click="testSendVisible = false">{{ t('common.cancel') }}</ElButton>
        <ElButton type="primary" @click="executeTestSend">发送</ElButton>
      </template>
    </ElDialog>
  </Page>
</template>
